INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21317$nota-0184$m21317$, $m21318$Manual treinamento.pdf$m21318$, $m21319$110$m21319$, $m21320$Stephen Seiler propôs uma abordagem diferente. Em vez de sete zonas, utiliza apenas três grandes domínios fisiológicos. Zona 1: Abaixo do LT1. Zona 2: Entre LT1 e LT2. Zona 3: Acima do LT2. Essa divisão simplifica o treinamento e possui forte relação com a fisiologia dos limiares. Grande parte das pesquisas sobre treinamento polarizado utiliza esse modelo.$m21320$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m21321$nota-0184$m21321$, $m21322$nota-0022$m21322$, $m21323$alternativa-a$m21323$, $m21324$modelo simplificado de 3 zonas (Seiler), usado na literatura de treinamento polarizado, versus os 7 níveis práticos de Coggan (%FTP) do Livro 1 — ambos válidos, granularidades diferentes$m21324$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m21325$nota-0184$m21325$, $m21326$nota-0178$m21326$, $m21327$complementa$m21327$, $m21328$o modelo de 3 zonas de Seiler é essencialmente os domínios Moderado/Pesado/Severo (nota-0178), sem o domínio Extremo separado$m21328$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21329$nota-0186$m21329$, $m21330$Manual treinamento.pdf$m21330$, $m21331$116$m21331$, $m21332$Sobrecarga: o estímulo precisa ser suficiente para perturbar a homeostase... Especificidade: o organismo adapta-se exatamente ao estímulo recebido... Progressão: à medida que o atleta adapta-se, novos estímulos tornam-se necessários... Reversibilidade: adaptações fisiológicas diminuem quando o treinamento é interrompido... Individualidade: dois atletas submetidos ao mesmo treinamento dificilmente apresentarão exatamente a mesma resposta.$m21332$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21333$nota-0188$m21333$, $m21334$Manual treinamento.pdf$m21334$, $m21335$125$m21335$, $m21336$Macrociclo: representa o planejamento de longo prazo... Mesociclo: conjunto de semanas com um objetivo específico... Normalmente possui duração entre três e seis semanas. Microciclo: corresponde à organização semanal do treinamento... É a unidade prática do planejamento.$m21336$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21337$nota-0189$m21337$, $m21338$Manual treinamento.pdf$m21338$, $m21339$126$m21339$, $m21340$A periodização clássica foi proposta por Lev Matveyev, na década de 1960. Seu modelo divide a temporada em três grandes fases: Período Preparatório (construção da base)... Período Competitivo (transformar capacidades em desempenho)... Período de Transição (recuperação física e psicológica).$m21340$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21341$nota-0189$m21341$, $m21342$Manual treinamento.pdf$m21342$, $m21343$127$m21343$, $m21344$Desenvolvida principalmente por Yuri Verkhoshansky e posteriormente expandida por Vladimir Issurin, a periodização em blocos propõe concentrar estímulos semelhantes em períodos relativamente curtos. Em vez de desenvolver todas as capacidades simultaneamente, trabalha-se com blocos especializados: bloco de força; bloco aeróbio; bloco de VO₂máx; bloco competitivo.$m21344$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21345$nota-0190$m21345$, $m21346$Manual treinamento.pdf$m21346$, $m21347$135$m21347$, $m21348$Treinos de VO₂máx realizados após longa sessão extenuante tendem a apresentar menor qualidade... Entre os princípios mais utilizados destacam-se: qualidade antes da quantidade; maior complexidade quando o atleta está descansado; recuperação ativa após sessões muito exigentes; evitar sobreposição excessiva de estímulos semelhantes.$m21348$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21349$nota-0192$m21349$, $m21350$Manual treinamento.pdf$m21350$, $m21351$144$m21351$, $m21352$Um dos primeiros métodos amplamente utilizados para quantificar carga interna foi o TRIMP (Training Impulse), proposto por Eric Banister. O método combina: duração; intensidade baseada na frequência cardíaca. Quanto maior o tempo e maior a intensidade, maior será o TRIMP da sessão. Apesar de suas limitações, permanece uma ferramenta útil quando medidores de potência não estão disponíveis.$m21352$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m21353$nota-0192$m21353$, $m21354$nota-0062$m21354$, $m21355$alternativa-a$m21355$, $m21356$TRIMP (baseado em FC/duração) é um método concorrente/antecessor histórico do TSS (baseado em potência/FTP, nota-0062 do Livro 1) para quantificar carga de treino — mesmo objetivo, entradas diferentes$m21356$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21357$nota-0247$m21357$, $m21358$Exercise Physiology McArdle.pdf$m21358$, $m21359$486$m21359$, $m21360$A 1- to 3-wk taper that exponentially reduces training volume by 40 to 60%, while maintaining training intensity, provides the most efficient strategy to maximize performance gains. A 4- to 7-day taper should provide sufficient time for maximum muscle and liver glycogen replenishment, optimal nutritional support and restoration, alleviation of residual muscle soreness, and healing of minor injuries.$m21360$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21361$nota-0247$m21361$, $m21362$Exercise Physiology McArdle.pdf$m21362$, $m21363$486$m21363$, $m21364$An optimal taper should include progressive reductions in training volume while maintaining training intensity at a moderate-to-high level. With proper tapering, expected performance improvement usually ranges between 0.5 and 6.0%. Tapering does not associate with substantial changes in exercise-induced oxidative stress.$m21364$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m21365$nota-0247$m21365$, $m21366$nota-0090$m21366$, $m21367$complementa$m21367$, $m21368$nota-0090 trata do ramp rate de aumento seguro de CTL; esta nota trata do lado oposto do ciclo — a redução deliberada de volume (taper) antes de competição$m21368$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m21369$nota-0249$m21369$, $m21370$Exercise Physiology McArdle.pdf$m21370$, $m21371$515$m21371$, $m21372$Debate concerns whether concurrent resistance and aerobic training yields less muscular strength and power improvement than training for strength only. [...] A short-term bout of intense endurance activity also inhibits performance in subsequent muscular strength activities. Further research must determine whether this acute effect on maximal force output limits ability to overload skeletal muscle optimally to a degree that impairs strength development with concurrent strength and endurance training. If it does, then a 20- to 30-min recovery between aerobic and strength-training components might enhance the quality of the subsequent strength workout.$m21372$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m21373$nota-0249$m21373$, $m21374$nota-0187$m21374$, $m21375$complementa$m21375$, $m21376$nota-0187 recomenda treino de força para ciclistas focado em capacidade neuromuscular; esta nota adiciona uma ressalva prática sobre como sequenciar/espaçar essa sessão de força em relação ao treino de bike no mesmo dia$m21376$)
